    def connect_to_one_click(self, ip, port, username="", password="", secure=False, verify=False):
        """
        provide connection to one click
        :param ip: Ip address to one click
        :param port: Port for connection to one click
        :param username: Username to one click, now is not used.
        :param password: Password to one click, now is not used.
        :param secure: Default 'False'. If set to `True`, the connection will be realized with use https prefix,
                       else with http.
        :param verify: Default 'False' for restapi request.
        :return: None
        """
        self._one_click_connection = OneClickConnection(
            ip=ip,
            port=port,
            username=username,
            password=password,
            secure=secure,
            verify=verify
        )

