    def helm_master_connect(self, ip, port, user, password, timeout="10"):
        """
        This keyword is used to helm master connect, helm master is k8s master
        *Args:*
            - _ip_: k8s master ip address(mandatory)
            - _user_: user name of k8s master (mandatory)
            - _password_: password of user (mandatory)
            - _port_: k8s master ssh port
            - _timeout_: timeout of login, default is 10s

        *Command:*  None
        *Returns:*
            - connection alias
        *Example:*
        | helm_master_connect | 10.11.56.34 | user |  password  | 22 |
         """
        conn = self.sshlib.connect_to(ip, user, password, port=port, timeout=timeout)
        return conn

    def helm_merge_values_file(self, local_src_file, remote_dst_file, conn=None):
        """
        This keyword is used to merge local values yaml file to remote values yaml file
        call after helm_master_connect
        *Args:*
            - _local_src_file_: full path of local yaml file(mandatory)
            - _remote_dst_file_: full path of rmeote yaml file (mandatory)
            - _conn_: connection object which returned from helm_master_connect (default is None)

        *Command:*  None
        *Returns:*
            - None
        *Example:*
        | helm_merge_values_file | /home/ute/values-override.yaml | /home/cranuser11/aic-vdu/values-override.yaml |
         """
        dst_file_name = os.path.basename(remote_dst_file)
        local_path = os.path.join("/tmp", time.strftime("%Y%m%d%H%M%S"))
        os.system("rm -rf {}".format(local_path))
        os.system("mkdir -p {}".format(local_path))
        local_dst_path = os.path.join(local_path, dst_file_name)
        try:
            self.sshlib.download_file(remote_dst_file, local_dst_path, conn)
            ValuesHandling().merge_values_file(local_src_file, local_dst_path)
            self.sshlib.upload_file(local_dst_path, remote_dst_file, conn)
        finally:
            os.system("rm -rf {}".format(local_path))

    def helm_master_close(self, conn=None):
        """
        This keyword is used to close ssh connection to k8s master
        *Command:*  None
        *Returns:*
            - None
        *Example:*
        | helm_master_close |  |
         """
        self.sshlib.disconnect(conn)

    def helm_upload_file_to_master(self, source, destination, conn=None):
        """
        This keyword is used to upload file to master
        *Args:*
            - _source_: path of file which will be uploaded in local PC (mandatory)
            - _destination_:  path of file will be uploaded in remote PC (mandatory)
            - _conn_: connection object which returned from helm_master_connect (default is None)
        *Command:*  None
        *Returns:*
            - None
        *Example:*
        | helm_upload_file_to_master |  values-override.yaml |  values-override.yaml |
         """
        self.sshlib.upload_file(source, destination, connection=conn)

    def helm_download_file_from_master(self, remote_path, local_path, conn=None):
        """
        This keyword is used to download file from master
        *Args:*
            - _remote_path_: path of file which will be downloaded in remote PC (mandatory)
            - _local_path_:  path of file will be downloaded in local PC (mandatory)
            - _conn_: connection object which returned from helm_master_connect (default is None)
        *Command:*  None
        *Returns:*
            - None
        *Example:*
        | helm_download_file_from_master |  values-override.yaml |  values-override.yaml |
         """
        self.sshlib.download_file(remote_path, local_path, connection=conn)

