    def kuashaw_oneclick_undeploy(self, target_path):
        self.kuashaw_oneclick_action(target_path, action="delete", script="kuashaw_lcm.py", conn=None)

    def kuashaw_oneclick_action(self,target_path, action="install", script="kuashaw_lcm.py", conn=None):
        """
        This keyword is used to delete/install/get status by using Kuashaw-oneClick
        *Args:*
            - _target_path_: path of  (mandatory)
            - _action_:  action of Kuashaw-oneClick: delete|install|status (mandatory)
            - _script_:  select script of Kuashaw-oneClick (mandatory, default is kuashaw_lcm.py)
            - _conn_: connection object which returned from helm_master_connect (default is None)
        *Command:*  None
        *Returns:*
            - None (when action=install, delete)
            - status (when action=status)
        *Example:*
        | kuashaw_oneclick_action | Kuashaw-oneClick-allinone | delete | kuashaw_lcm.py
        | kuashaw_oneclick_action | Kuashaw-oneClick-allinone | install | kuashaw_lcm.py
        | kuashaw_oneclick_action | Kuashaw-oneClick-allinone | status | kuashaw_lcm.py
        """
        # command_lcm = "kuashaw_lcm.py install|delete|status "
        py_file = script
        second_path = "Kuashaw-oneClick-" + py_file.split(".")[0].split("_")[-1]
        command = "python " + target_path + "/" + second_path + "/" + py_file + " " + action
        result = self.execute_command_on_master_cluster(command, True, conn=conn)
        if action == 'status':
            return result.stdout

    def __get_storage_class_name(self, conn):
        class_name = "ocs-storagecluster-cephfs"
        node_num = self.execute_command_on_master_cluster("oc get nodes | grep -v STATUS | wc -l", conn=conn)
        if int(node_num.stdout) <= 2:
            class_name = self.execute_command_on_master_cluster("kubectl get sc | "
                                                                "grep -v ALLOWVOLUMEEXPANSION | "
                                                                "awk '{print $1}'",
                                                                conn=conn).stdout.strip()
        return class_name

