    def _untar_on_board_tool(self,
                             target_path,
                             on_board_tool_name="onBoardingApp.tgz",
                             conn=None):
        full_path = target_path.rstrip("/") + "/" + on_board_tool_name
        self.sshlib.file_exists(full_path, conn)
        untar_command = "tar zxvf {} -C {}".format(full_path, target_path)
        self.execute_command_on_master_cluster(untar_command, True, conn=conn)
        target_path = target_path.rstrip("/") + "/{}".format(os.path.splitext(on_board_tool_name)[0])
