    def helm_get_release_list(self, namespace="default",
                              fail_on_error=True,
                              conn=None,
                              all=False):
        """
        *Args:*
            - _fail_on_error_: see `Failing on command execution errors`
            - _all_: if set to True, will add -a
        *Command:* ``helm list

        *Returns:*
            - `result as list of dict have following attribute
               name
               revision
               updated
               status
               chart
               app_ver
               namespace

        *Example:*
        | ${result} | helm list | namespace
        """
        cmd = 'helm list -n {}'.format(namespace)
        if str(all).lower().strip() == "true":
            cmd += " -a "
        cmd = cmd + r" |awk -F '\t' " + "'{0}print $1 {1} $3 {1} $4 {1} $5 {1} $6 {1} $7 {1} $2{2}'".format(
            "{", '\"\\t\"', "}")
        result = self.execute_command_on_master_cluster(cmd, fail_on_error, conn=conn)
        return self._get_parsed_helm_list(result.stdout)

