    def _get_helm_list_result_header(self, lines):
        while True:
            header = lines.pop(0)
            if header.strip().startswith("NAME"):
                break
        return header

    def helm_get_status(self, release_name, fail_on_error=True, conn=None):
        """
        get helm status
        *Args:*
            - release_name - : release name which will be handled
            - _fail_on_error_: see `Failing on command execution errors`
        *Command:* ``helm status release_name

        *Returns:*
            - `nested dictionary
               - super key map:
                  - status   ---  status of helm, DEPLOYED or Error
                  - configmap --- configmap related information
                  - pvc --- Persistent Volume Claim related infomation
                  - pod --- pod releated information
                  - svc --- service related information
                  - sts --- StatefulSet releated information
                  - tnet --- tenant network related information

               - key of super key:
                  - configmap
                      - name
                      - data
                      - age
                  - pvc
                      - name
                      - status
                      - volume
                      - capacity
                      - access_mode
                      - storageclass
                      - age
                  - pod
                      - name
                      - ready
                      - status
                      - restarts
                      - age
                  - svc
                      - name
                      - type
                      - cluster_ip
                      - external_ip
                      - port
                      - age
                  - sts
                      - name
                      - ready
                      - age
                  - tnet
                      - name
                      - age

        *Example:*
        | ${result} | helm status |
        """
        cmd = 'helm status {}'.format(release_name)
        result = self.execute_command_on_master_cluster(cmd, fail_on_error, conn=conn)
        return self._get_parsed_helm_status(result.stdout)

    def are_all_pvcs_in_bound_status(self, namespace='default', fail_on_error=True, conn=None):
        """
        are all pvcs in bound status  -- check whether all pvc in bound status
        *Args:*
            - namespace - :  namespace
            - _fail_on_error_: see `Failing on command execution errors`
            - conn
        *Command:* ``are all pvcs in bound status

        *Returns:*
            True or False

        *Example:*
        | ${result} | are all pvcs in bound status | cran1 |
        """
        bound_pvc_cmd = 'kubectl get pvc -n {} | grep Bound | wc -l'.format(namespace)
        all_pvc_cmd = 'kubectl get pvc -n {} | grep -v CAPACITY | wc -l'.format(namespace)
        bound_pvc_num = self.execute_command_on_master_cluster(bound_pvc_cmd, fail_on_error, conn=conn)
        all_pvc_num = self.execute_command_on_master_cluster(all_pvc_cmd, fail_on_error, conn=conn)
        if int(bound_pvc_num.stdout.strip()) == int(all_pvc_num.stdout.strip()):
            return True
        return False

    def _are_all_pods_running_ok(self, namespace='default', fail_on_error=True, conn=None):
        cmd = 'kubectl get pod -n {}'.format(namespace)
        result = self.execute_command_on_master_cluster(cmd, fail_on_error, conn=conn)
        parsed_result = self._get_parsed_pod(result.stdout)
        if not self._are_all_pod_status_ok(parsed_result):
            return False
        return True

    def _is_running_pod_number_matched(self, namespace='default', pod_number='13', fail_on_error=True, conn=None):
        cmd = 'kubectl get pod -n {} |grep Running |  wc -l'.format(namespace)
        if pod_number == "NA":
            return True
        result = self.execute_command_on_master_cluster(cmd, fail_on_error, conn=conn)
        if int(str(result.stdout).strip()) != int(pod_number):
            return False
        return True

    def _are_all_pod_status_ok(self, parsed_result):
        for line in parsed_result:
            if line["status"] != 'Running':
                return False
        return True

    def _get_parsed_pod(self, kubectl_get_pod_output):
        lines = kubectl_get_pod_output.splitlines()
        header = self._get_helm_list_result_header(lines)
        result = []
        for line in lines:
            item = self._get_kubectl_get_pod_header_items(header, line)
            result.append(item)
        return result

    def wait_until_all_pods_deleted(self, namespace='default', fail_on_error=True, timeout="300", conn=None):
        max_time = time.time() + float(timeout)
        while time.time() < max_time:
            cmd = 'kubectl get pod -n {}'.format(namespace)
            result = self.execute_command_on_master_cluster(cmd, fail_on_error, conn=conn)
            if "no resources found" in result.stderr.lower():
                return True
            else:
                time.sleep(5)
        raise TimeoutError("Uninstall failed by {}".format(str(result)))

    def _get_parsed_helm_status(self, helm_status_output):
        blocks = helm_status_output.split("==>")
        result = {}
        for block in blocks:
            parse_result = self._parse_block(block)
            if parse_result:
                result[parse_result["resource_name"]] = parse_result["result"]
        return result

    def _parse_block(self, block):
        block_handlers = [
            ("STATUS:", self._parse_global_block),
            ("/ConfigMap", self._parse_configmap_block),
            ("/PersistentVolumeClaim", self._parse_pvc_block),
            ("/Pod", self._parse_pod_block),
            ("/Service", self._parse_service_block),
            ("/StatefulSet", self._parse_sts_block),
            ("/TenantNetwork", self._parse_tenant_network_block)
        ]
        for key, handler in block_handlers:
            if key in block:
                return handler(block)
        return None

    def _parse_global_block(self, block):
        group = re.search("STATUS:(.*)", block)
        if group:
            return {"resource_name": "status", "result": group.group(1).strip()}
        return None

    def _parse_k8s_resource_table(self, resource_name, block, pattern, key_list):
        result = re.findall(pattern, block)
        if not result:
            return None
        config_result = []
        for item in result:
            tmp = {}
            for i in range(len(key_list)):
                tmp[key_list[i]] = item[i]
            config_result.append(tmp)
        return {"resource_name": resource_name, "result": config_result}

    def _parse_configmap_block(self, block):
        return self._parse_k8s_resource_table("configmap", block, r"(\S+)\s+(\d+)\s+(\S+)", ["name", "data", "age"])

    def _parse_pvc_block(self, block):
        return self._parse_k8s_resource_table("pvc", block, r"(\S+)\s+(\S+)\s+(\S+)\s+(\d+\w+)\s+(\S+)\s+(\S+)\s+(\S+)",
                                              ["name", "status", "volume", "capacity", "access_mode", "storageclass",
                                               "age"])

    def _parse_pod_block(self, block):
        return self._parse_k8s_resource_table("pod", block, r"(\S+)\s+(\d+/\d+)\s+(\S+)\s+(\d+)\s+(\S+)",
                                              ["name", "ready", "status", "restarts", "age"])

    def _parse_service_block(self, block):
        return self._parse_k8s_resource_table("svc", block, r"(\S+)\s+(\S+)\s+(\S+)\s+(\S+)\s+(\S+/\S+)\s+(\S+)",
                                              ["name", "type", "cluster_ip", "external_ip", "port", "age"])

    def _parse_sts_block(self, block):
        return self._parse_k8s_resource_table("sts", block, r"(\S+)\s+(\d+/\d+)\s+(\S+)",
                                              ["name", "ready", "age"])

    def _parse_tenant_network_block(self, block):
        return self._parse_k8s_resource_table("tnet", block, r"(\S+)\s+(\d\w\S+)",
                                              ["name", "age"])

    def _get_helm_list_header_items(self, header, line):
        item = {}
        item["name"] = line[header.index("NAME"): header.index("REVISION")].strip()
        item["revision"] = line[header.index("REVISION"): header.index("UPDATED")].strip()
        item["updated"] = line[header.index("UPDATED"): header.index("STATUS")].strip()
        item["status"] = line[header.index("STATUS"): header.index("CHART")].strip()
        item["chart"] = line[header.index("CHART"): header.index("APP VERSION")].strip()
        item["app_ver"] = line[header.index("APP VERSION"): header.index("NAMESPACE")].strip()
        item["namespace"] = line[header.index("NAMESPACE"):].strip()
        return item

    def _get_kubectl_get_pod_header_items(self, header, line):
        item = {}
        item["name"] = line[header.index("NAME"): header.index("READY")].strip()
        item["ready"] = line[header.index("READY"): header.index("STATUS")].strip()
        item["status"] = line[header.index("STATUS"): header.index("RESTARTS")].strip()
        item["restarts"] = line[header.index("RESTARTS"): header.index("AGE")].strip()
        item["age"] = line[header.index("AGE"):].strip()
        return item

    def _get_parsed_helm_list(self, stdout_result):
        lines = stdout_result.splitlines()
        header = self._get_helm_list_result_header(lines)
        result = []
        for line in lines:
            if len(line.split()) < 5:
                continue
            item = self._get_helm_list_header_items(header, line)
            result.append(item)
        return result

    def _check_resource_ready(self, resource_name, helm_status_result):
        if resource_name in helm_status_result:
            for pod_item in helm_status_result[resource_name]:
                ready = pod_item["ready"].split("/")
                if ready[0] != ready[1]:
                    return False
        return True

    def _check_created_objects_status(self, release_name, namespace='default', conn=None, ishelm3=False, pod_number='13'):
        if ishelm3:
            kubectl_get_pod_result = self._are_all_pods_running_ok(namespace, conn=conn)
            kubectl_get_pod_grep_running_result = self._is_running_pod_number_matched(namespace, pod_number)
            print('kubectl_get_pod_result', kubectl_get_pod_result)
            print('kubectl_get_pod_grep_running_result', kubectl_get_pod_grep_running_result)
            if not kubectl_get_pod_result or not kubectl_get_pod_grep_running_result:
                return False
        else:
            helm_status_result = self.helm_get_status(release_name, conn=conn)
            pod_check = self._check_resource_ready("pod", helm_status_result)
            sts_check = self._check_resource_ready("sts", helm_status_result)
            if not sts_check or not pod_check:
                return False
        return True

